INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Kann ich Performance ohne Monitoring bewerten?', 2, '[{"text": "Nein", "correct": true, "because": "Monitoring liefert Daten"}, {"text": "Ja", "correct": false, "because": "Ungenau ohne Messung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit der Bewertung von Performance?', 3, '[{"text": "Leistungsoptimierung", "correct": true, "because": "Erkennt Engpässe"}, {"text": "UI-Design", "correct": false, "because": "Anderer Fokus"}, {"text": "Marketing", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methoden nutze ich zur Performance-Bewertung?', 5, '[{"text": "Monitoring-Tools", "correct": true, "because": "Liefert Echtzeitdaten"}, {"text": "Benchmarks", "correct": true, "because": "Vergleicht Leistung"}, {"text": "Zufällige Schätzung", "correct": false, "because": "Unzuverlässig"}, {"text": "Manuelle Tests", "correct": false, "because": "Zeitaufwendig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Funktionalität wird durch Tests geprüft. b) Performance ist immer sichtbar.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) oft versteckt"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Performance-Bewertung?', 4, '[{"text": "Metriken", "correct": false, "because": "Misst Leistung"}, {"text": "Ladezeiten", "correct": false, "because": "Zeigt Effizienz"}, {"text": "Schriftfarbe", "correct": true, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Funktionalität ohne Nutzerfeedback geprüft werden kann?', 2, '[{"text": "Ja", "correct": true, "because": "Tests reichen"}, {"text": "Nein", "correct": false, "because": "Feedback ergänzt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Tool nutze ich für Performance-Monitoring?', 3, '[{"text": "New Relic", "correct": true, "because": "Überwacht Leistung"}, {"text": "Notepad", "correct": false, "because": "Kein Monitoring"}, {"text": "E-Mail", "correct": false, "because": "Unpraktisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren machen eine Bewertung effektiv?', 5, '[{"text": "Echtzeitdaten", "correct": true, "because": "Aktuelle Einblicke"}, {"text": "Testabdeckung", "correct": true, "because": "Prüft Funktionen"}, {"text": "Hohe Auflösung", "correct": false, "because": "Irrelevant"}, {"text": "Lange Texte", "correct": false, "because": "Ermüdend"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Performance ist nur CPU. b) Funktionalität braucht keine Tests. Stimmt das?', 3, '[{"text": "Beides falsch", "correct": true, "because": "a) auch RAM, b) Tests nötig"}, {"text": "Beides stimmt", "correct": false, "because": "Nicht korrekt"}, {"text": "Nur a) stimmt", "correct": false, "because": "a) unvollständig"}, {"text": "Nur b) stimmt", "correct": false, "because": "b) falsch"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für die Performance-Bewertung?', 4, '[{"text": "Latenzdaten", "correct": false, "because": "Misst Reaktion"}, {"text": "CPU-Auslastung", "correct": false, "because": "Zeigt Leistung"}, {"text": "Papierformat", "correct": true, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist Funktionalität immer messbar?', 2, '[{"text": "Ja", "correct": true, "because": "Durch Tests prüfbar"}, {"text": "Nein", "correct": false, "because": "Messbar mit Tools"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Metriken sind bei der Bewertung entscheidend?', 4, '[{"text": "Responezeit", "correct": true, "because": "Zeigt Geschwindigkeit"}, {"text": "Fehlerquote", "correct": true, "because": "Prüft Stabilität"}, {"text": "Design-Details", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Performance-Bewertung einmalig ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Laufende Überwachung nötig"}, {"text": "Ja", "correct": false, "because": "Dynamisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Funktionalitätsbewertung?', 3, '[{"text": "Testabdeckung", "correct": true, "because": "Sichert Features"}, {"text": "Schnelle Durchführung", "correct": false, "because": "Qualität zählt"}, {"text": "Subjektive Meinungen", "correct": false, "because": "Unzuverlässig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Monitoring misst Performance. b) Funktionalität ist immer perfekt.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) nicht garantiert"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet eine gute Performance-Bewertung?', 5, '[{"text": "Optimierung", "correct": true, "because": "Erkennt Schwächen"}, {"text": "Stabilität", "correct": true, "because": "Verhindert Ausfälle"}, {"text": "Hohe Kosten", "correct": false, "because": "Kein Vorteil"}, {"text": "Schnelle Entwicklung", "correct": false, "because": "Indirekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Bewertung unwichtig?', 3, '[{"text": "Fehlerprotokolle", "correct": false, "because": "Zeigt Probleme"}, {"text": "Ladezeiten", "correct": false, "because": "Misst Effizienz"}, {"text": "Monitorgröße", "correct": true, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ersetzt Monitoring die Tests?', 3, '[{"text": "Nein", "correct": true, "because": "Ergänzen sich"}, {"text": "Ja", "correct": false, "because": "Tests prüfen Funktionen"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Performance nur CPU betrifft?', 2, '[{"text": "Nein", "correct": true, "because": "Auch RAM, Netzwerk"}, {"text": "Ja", "correct": false, "because": "Nicht exklusiv"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Feature ist für die Bewertung entscheidend?', 4, '[{"text": "Metriken", "correct": true, "because": "Liefert objektive Daten"}, {"text": "Hohe Taktfrequenz", "correct": false, "because": "Hardware-spezifisch"}, {"text": "Manuelle Prüfung", "correct": false, "because": "Zu langsam"}]');
